create table constitution.decision_intelligence_requests (id uuid primary key default gen_random_uuid(),request_code text not null unique,experiment_id uuid not null references constitution.strategy_evolution_experiments(id) on delete cascade,requested_by text,decision_question text not null,audience text not null default 'founder',explanation_depth text not null default 'executive',status text not null default 'queued',founder_approval_required boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check (explanation_depth in ('executive','operational','technical','audit')),check (status in ('queued','processing','completed','failed','awaiting_approval')));
create table constitution.decision_recommendations (id uuid primary key default gen_random_uuid(),request_id uuid not null references constitution.decision_intelligence_requests(id) on delete cascade,experiment_id uuid not null references constitution.strategy_evolution_experiments(id) on delete cascade,selected_candidate_id uuid references constitution.strategy_candidates(id),recommendation_code text not null unique,recommendation_status text not null default 'draft',executive_recommendation text not null,decision_summary jsonb not null default '{}'::jsonb,confidence numeric(6,5) not null default 0,confidence_band text not null,expected_value numeric(12,6),risk_adjusted_score numeric(12,6),evidence_strength numeric(6,5) not null default 0,uncertainty_summary jsonb not null default '{}'::jsonb,approval_status text not null default 'pending',approved_by text,approved_at timestamptz,created_at timestamptz not null default now(),check (recommendation_status in ('draft','ready','withheld','superseded')),check (confidence between 0 and 1),check (evidence_strength between 0 and 1),check (approval_status in ('pending','approved','rejected','not_required')));
create table constitution.decision_option_assessments (id uuid primary key default gen_random_uuid(),recommendation_id uuid not null references constitution.decision_recommendations(id) on delete cascade,candidate_id uuid not null references constitution.strategy_candidates(id) on delete cascade,rank integer not null,option_status text not null,expected_value numeric(12,6),risk_adjusted_score numeric(12,6),confidence numeric(6,5) not null default 0,strengths jsonb not null default '[]'::jsonb,weaknesses jsonb not null default '[]'::jsonb,tradeoffs jsonb not null default '{}'::jsonb,constraint_findings jsonb not null default '{}'::jsonb,why_selected_or_rejected text not null,created_at timestamptz not null default now(),unique(recommendation_id,candidate_id),check(rank>0),check(confidence between 0 and 1),check(option_status in ('recommended','alternative','ineligible','insufficient_evidence')));